cor <- function(x, y,na.rm=FALSE){
    if(na.rm==TRUE){
        which_id <- !is.na(x)
        x <- x[which_id]
        y <- y[which_id]
    }
    N <- length(y)
    mean_x <- sum(x)/N
    mean_y <- sum(y)/N
    correlation <- ( (x-mean_x) %*% (y-mean_y) /(N-1)) / ( sqrt(sum((x-mean_x)^2)/(N-1)) * sqrt(sum((y-mean_y)^2)/(N-1)))
    return(correlation)
}
